    assert(2*weeks + extra_max <= 2*weeks + rem);

    // 5) 2*weeks ≤ 7*weeks  (since weeks ≥ 0)
    assert(2*weeks <= 7*weeks);

    // 6) Thus 2*weeks + rem ≤ 7*weeks + rem = n
    assert(2*weeks + rem <= 7*weeks + rem);
    assert(7*weeks + rem == n);

